Approach: the counter hooks `set_trace_callback` and filters on the first keyword. The naive loader executes one message query per conversation; the batched loader groups messages by conversation in Python after one `IN` query per chunk, which is what `selectinload` does (it chunks the parent keys, 500 at a time). The budget helpers are plain arithmetic.

**`nplus1.py`**

```python
from __future__ import annotations

import sqlite3
from collections import defaultdict
from collections.abc import Iterator
from dataclasses import dataclass
from types import TracebackType


class QueryCounter:
    """Counts SELECT statements executed on a sqlite3 connection."""

    def __init__(self, conn: sqlite3.Connection) -> None:
        self._conn = conn
        self.statements: list[str] = []

    @property
    def count(self) -> int:
        return len(self.statements)

    def __enter__(self) -> QueryCounter:
        self._conn.set_trace_callback(self._record)
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self._conn.set_trace_callback(None)

    def _record(self, statement: str) -> None:
        if statement.lstrip().upper().startswith("SELECT"):
            self.statements.append(statement)


def load_naive(conn: sqlite3.Connection, user_id: str) -> dict[int, list[str]]:
    result: dict[int, list[str]] = {}
    parents = conn.execute("SELECT id FROM conversations WHERE user_id = ? ORDER BY id", (user_id,)).fetchall()
    for (cid,) in parents:
        rows = conn.execute("SELECT body FROM messages WHERE conversation_id = ? ORDER BY id", (cid,)).fetchall()
        result[cid] = [body for (body,) in rows]
    return result


def _chunks(items: list[int], size: int) -> Iterator[list[int]]:
    for start in range(0, len(items), size):
        yield items[start:start + size]


def load_batched(conn: sqlite3.Connection, user_id: str, chunk_size: int = 500) -> dict[int, list[str]]:
    if chunk_size < 1:
        raise ValueError("chunk_size must be >= 1")
    ids = [cid for (cid,) in conn.execute("SELECT id FROM conversations WHERE user_id = ? ORDER BY id", (user_id,))]
    grouped: dict[int, list[str]] = defaultdict(list)
    for chunk in _chunks(ids, chunk_size):
        marks = ",".join("?" * len(chunk))
        sql = f"SELECT conversation_id, body FROM messages WHERE conversation_id IN ({marks}) ORDER BY id"
        for cid, body in conn.execute(sql, chunk):
            grouped[cid].append(body)
    return {cid: grouped.get(cid, []) for cid in ids}


@dataclass(frozen=True)
class Budget:
    worst_case: int
    available: int

    @property
    def fits(self) -> bool:
        return self.worst_case <= self.available


def connection_budget(
    replicas: int, workers: int, pool_size: int, max_overflow: int, max_connections: int, reserved: int
) -> Budget:
    return Budget(replicas * workers * (pool_size + max_overflow), max_connections - reserved)


def largest_pool_size(
    replicas: int, workers: int, max_connections: int, reserved: int, overflow_ratio: float = 0.5
) -> int:
    available = max_connections - reserved
    best = 0
    size = 1
    while replicas * workers * (size + int(size * overflow_ratio)) <= available:
        best = size
        size += 1
    return best
```

**`test_nplus1.py`**

```python
import sqlite3

from nplus1 import QueryCounter, connection_budget, largest_pool_size, load_batched, load_naive


def make_db(parents: int, per_parent: int = 2) -> sqlite3.Connection:
    conn = sqlite3.connect(":memory:")
    conn.executescript(
        """
        CREATE TABLE conversations (id INTEGER PRIMARY KEY, user_id TEXT);
        CREATE TABLE messages (id INTEGER PRIMARY KEY, conversation_id INTEGER, body TEXT);
        """
    )
    conn.executemany("INSERT INTO conversations(id, user_id) VALUES (?, 'u1')", [(i,) for i in range(1, parents + 1)])
    conn.executemany(
        "INSERT INTO messages(conversation_id, body) VALUES (?, ?)",
        [(c, f"{c}-{k}") for c in range(1, parents + 1) for k in range(per_parent)],
    )
    conn.execute("INSERT INTO conversations(id, user_id) VALUES (?, 'u2')", (parents + 1,))
    conn.commit()
    return conn


def test_naive_is_n_plus_one():
    conn = make_db(50)
    with QueryCounter(conn) as qc:
        data = load_naive(conn, "u1")
    assert qc.count == 51 and len(data) == 50


def test_batched_matches_naive_with_two_queries():
    conn = make_db(50)
    with QueryCounter(conn) as qc:
        batched = load_batched(conn, "u1")
    assert qc.count == 2
    assert batched == load_naive(conn, "u1")


def test_chunking_is_ceil_division():
    conn = make_db(1200, per_parent=1)
    with QueryCounter(conn) as qc:
        load_batched(conn, "u1", chunk_size=500)
    assert qc.count == 1 + 3
    with QueryCounter(conn) as qc:
        load_batched(conn, "u1", chunk_size=1200)
    assert qc.count == 2


def test_parents_without_children_and_no_parents():
    conn = make_db(3)
    conn.execute("DELETE FROM messages WHERE conversation_id = 2")
    assert load_batched(conn, "u1")[2] == []
    with QueryCounter(conn) as qc:
        assert load_batched(conn, "nobody") == {}
    assert qc.count == 1


def test_counter_detaches():
    conn = make_db(2)
    with QueryCounter(conn) as qc:
        conn.execute("SELECT 1")
    conn.execute("SELECT 2")
    assert qc.count == 1


def test_budget():
    b = connection_budget(2, 3, 10, 5, 100, 20)
    assert (b.worst_case, b.available, b.fits) == (90, 80, False)
    assert connection_budget(2, 3, 9, 4, 100, 20).fits
    assert largest_pool_size(2, 3, 100, 20) == 9
    assert largest_pool_size(100, 100, 100, 20) == 0
```

Run with `pytest -q` from the directory containing both files (all six tests pass).
